  $Ae = `Přidání vrstvy rozvržení (při míření)`,
  eje = `Odebrání vrstvy rozvržení (při míření)`,
  tje = `Popadněte svůj ovladač!`,
  nje = `Tato hra vyžaduje ke hraní ovladač.`,
  rje = `Váš <1></1> by měl fungovat bez problémů!`,
  ije = `Doteď jste nepoužili žádný ovladač, ale libovolný ovladač Xbox nebo PlayStation by měl stačit.`,
  aje = `Popadněte ovladač a udělejte si pohodlí!`,
  oje = `Tato hra vyžaduje pro co nejlepší zážitek ovladač. Vezměte tedy do ruky ovladač Steam Controller, Xbox nebo jakékoli jiné zařízení, které vypadá jako ovladač a lze ho připojit k\xA0počítači.`,
  sje = `Znovu nezobrazovat`,
  cje = `Tuto možnost vyberte, pokud hra pro ovládání kamery nebo kurzoru očekává vstup myši.`,
  lje = `Tuto možnost vyberte, pokud hra pro ovládání kamery nebo kurzoru očekává vstup páčky.`,
  uje = `Tuto možnost vyberte, pokud hra pro ovládání kurzoru myši či kamery z pohledu první nebo třetí osoby používá vstup myši.`,
  dje = `Tuto možnost vyberte, pokud hra pro ovládání kurzoru myši či kamery z pohledu první nebo třetí osoby používá vstup páčky. Hře tak bude poskytnut vstup páčky, ale Vaše pohyby po trackpadu budou interpretovány jako pohyby myši.`,
  fje = `Kruhová nabídka dostává svému názvu a její tlačítka jsou uspořádána do kruhu.`,
  pje = `Dotyková nabídka je mřížka tlačítek uzpůsobená pro snadné ovládání pomocí trackpadu.`,
  mje = `Rychlá nabídka je lineární výčet tlačítek, kterými lze jedno po druhém procházet.`,
