  Oet = `Tlumení spouští bude vypnuté.`,
  ket = `Tlumení jemným stiskem pravé spouště`,
  Aet = `Tlumení bude zapnuté pro jemný stisk pravé spouště. Stiskem spouště tak bude možné utlumit pohyby myši, dokud nebude dosaženo jejího úplného stisknutí.`,
  jet = `Tlumení jemným stiskem levé spouště`,
  Met = `Tlumení bude zapnuté pro jemný stisk levé spouště. Stiskem spouště tak bude možné utlumit pohyby myši, dokud nebude dosaženo jejího úplného stisknutí.`,
  Net = `Tlumení jemným stiskem obou spouští`,
  Pet = `Tlumení bude zapnuté pro jemný stisk obou spouští. Stiskem jedné ze spouští tak bude možné utlumit pohyby myši, dokud nebude dosaženo jejího úplného stisknutí.`,
  Fet = `Tlumení jemným/úplným stiskem pravé spouště`,
  Iet = `Tlumení bude zapnuté pro jemný/úplný stisk pravé spouště. Stiskem spouště, včetně jejího úplného stisknutí, tak bude možné utlumit pohyby myši. Tlumení bude přerušeno až úplným puštěním spouště.`,
  Let = `Tlumení jemným/úplným stiskem levé spouště`,
  Ret = `Tlumení bude zapnuté pro jemný/úplný stisk levé spouště. Stiskem spouště, včetně jejího úplného stisknutí, tak bude možné utlumit pohyby myši. Tlumení bude přerušeno až úplným puštěním spouště.`,
  zet = `Tlumení jemným/úplným stiskem obou spouští`,
  Bet = `Tlumení bude zapnuté pro jemný/úplný stisk obou spouští. Stiskem jedné ze spouští, včetně jejího úplného stisknutí, tak bude možné utlumit pohyby myši. Tlumení bude přerušeno až úplným puštěním spouště.`,
  Vet = `Míra tlumení spouští`,
  Het = `Tato možnost určuje, jak moc budou utlumeny pohyby myši. Znatelnější zastavení zajistí posuvník více vpravo.`,
  Uet = `Dotek`,
  Wet = `Při dotýkání se trackpadu může být hře odesílán jiný signál (tlačítko/klávesa), který si nastavíte. Pokud je aktivní zrychlení myši / režim trackballu, přestane se signál odesílat, až kompletně ustane pohyb. Jinak se přestane odesílat hned, jak se přestanete trackpadu dotýkat.`,
  Get = `Práh naklonění gyroskopu`,
  Ket = `Tato možnost určuje, jak moc musí být ovladač nakloněn, aby byl odeslán signál přiřazený k naklonění.`,
  qet = `Naklonění doprava`,
  Jet = `Tento signál bude hře odeslán při naklánění ovladače na ose, která není používána pro ovládání.`,
  Yet = `Naklonění doleva`,
  Xet = `Tento signál bude hře odeslán při naklánění ovladače na ose, která není používána pro ovládání.`,
  Zet = `Režim trackballu`,
  Qet = `V tomto režimu bude trackpad brán jako trackball a ne jako myš. Bude tedy mít hybnost a tření a bude možné jej „roztočit“ jako trackball.`,
  $et = `Režim trackballu – zapnuto`,
  ett = `Myš bude brána jako trackball. Bude tedy mít hybnost a tření a bude možné ji roztočit jako trackball.`,
  ttt = `Režim trackballu – vypnuto`,
  ntt = `Myš se bude chovat jako klasická počítačová myš. Nebude mít hybnost ani tření.`,
  rtt = `Citlivost`,
  itt = `Tato možnost určuje citlivost tohoto vstupu. POZNÁMKA: Jelikož je hrami tato funkce vnímána pouze jako páčka, je citlivost omezena nastavením v nich. Pro dosažení co nejlepších výsledků proto nastavte citlivost kamery ve hrách při ovládání gamepadem na nejvyšší možnou hodnotu.`,
  att = `Natočení`,
  ott = `Natočení určuje přesnost vodorovného pohybu myši. Pokud trackpad rychle přejedete palcem, může být výsledný pohyb maličko nepřesný, respektive nakloněný. Proto můžete natočení zarovnat tak, aby odpovídalo přirozeným pohybům a rychlé přejetí vyústilo v přesný vodorovný pohyb.`,
  stt = `Intenzita hmatové odezvy`,
  ctt = `Tato možnost nastavuje intenzitu hmatové odezvy.`,
  ltt = `Intenzita hmatové odezvy – vypnuto`,
  utt = `Vypne hmatovou odezvu.`,
  dtt = `Intenzita hmatové odezvy – nízká`,
  ftt = `Intenzita hmatové odezvy bude na nízké úrovni.`,
