  xtt = `Signál po naklonění doprava`,
  Stt = `Tento signál bude odeslán, když nakloníte ovladač doprava.`,
  Ctt = `Tření trackballu`,
  wtt = `Tření trackballu určuje, za jak dlouho se trackball zastaví, když se volně točí.`,
  Ttt = `Tření trackballu – vypnuto`,
  Ett = `Pokud je možnost vypnuta, nebude mít trackball žádnou hybnost, tudíž se fyzický vstup bude chovat, jako kdyby nebyl trackball vůbec zapnut.`,
  Dtt = `Tření trackballu – malé`,
  Ott = `Pokud je tření malé, trackball se bude točit dlouhou dobu poté, co je roztočen a velmi pomalu se bude zastavovat.`,
  ktt = `Tření trackballu – střední`,
  Att = `Pokud je tření střední, trackball se bude točit chvíli poté, co je roztočen a postupně se bude zastavovat.`,
  jtt = `Tření trackballu – velké`,
  Mtt = `Pokud je tření velké, trackball se bude točit velmi krátkou chvíli poté, co je roztočen a téměř okamžitě se zastaví.`,
  Ntt = `Tření trackballu – nulové`,
  Ptt = `Pokud je tření nulové, trackball se bude po roztočení točit do té doby, než bude zastaven uživatelem.`,
  Ftt = `Měřítko tření svislé osy`,
  Itt = `Tření svislé osy určuje, za jak dlouho se zastaví pohyb po svislé ose v porovnání s pohybem po vodorovné ose. Pokud je puntík posuvníku přibližně v polovině, bude rychlost zastavení stejná. Pokud je puntík před polovinou, zastaví se pohyb po svislé ose rychleji, zatímco puntík za polovinou zajistí opak. Pro hry, kde trackballem ovládáte kameru, je vhodné mít velké svislé tření, jelikož se trackball přesouvá převážně do stran, tedy po vodorovné ose.`,
  Ltt = `Měřítko citlivosti svislé osy`,
  Rtt = `Měřítko citlivosti svislé osy určuje, jak velký pohyb po svislé ose nastane v porovnání s pohybem po vodorovné ose. Pokud je puntík posuvníku přibližně v polovině, budou pohyby stejně velké. Pokud je puntík před polovinou, pohyb po svislé ose bude menší než pohyb po ose vodorovné, zatímco puntík za polovinou zajistí větší pohyb po svislé ose.`,
  ztt = `Vyhlazování`,
  Btt = `Vyhlazování pomáhá odstranit šum a chvění myši. Nižší hodnoty vyústí v menší vyhlazování, zatímco vyšší hodnoty zajistí filtrování a vyhlazení pohybu.`,
  Vtt = `Akcelerace`,
  Htt = `Akcelerace určuje, že rychlejší pohyby myši způsobí větší pohyb v porovnání s pomalými pohyby na stejném prostoru trackpadu.`,
  Utt = `Akcelerace – vypnuta`,
  Wtt = `S nulovou akcelerací je vzdálenost přejetí prstem po trackpadu převedena na výstupní hodnotu v poměru 1:1, nezávisle na rychlosti přejetí.`,
  Gtt = `Akcelerace – nízká`,
  Ktt = `S nízkou akcelerací je vzdálenost rychlého přejetí prstem po trackpadu převedena na výstupní hodnotu s mírným navýšením.`,
  qtt = `Akcelerace – střední`,
  Jtt = `Se střední akcelerací je vzdálenost rychlého přejetí prstem po trackpadu převedena na výstupní hodnotu se znatelným navýšením.`,
  Ytt = `Akcelerace – vysoká`,
  Xtt = `S vysokou akcelerací je vzdálenost rychlého přejetí prstem po trackpadu převedena na výstupní hodnotu s velkým navýšením.`,
  Ztt = `Akcelerace`,
  Qtt = `Akcelerace určuje, že rychlejší pohyby myši způsobí větší pohyb v porovnání s pomalými pohyby na stejném prostoru trackpadu.`,
  $tt = `Akcelerace – vypnuta`,
  ent = `S nulovou akcelerací je vzdálenost přejetí prstem po trackpadu převedena na výstupní hodnotu v poměru 1:1, nezávisle na rychlosti přejetí.`,
  tnt = `Akcelerace – nízká`,
  nnt = `S nízkou akcelerací je vzdálenost rychlého přejetí prstem po trackpadu převedena na výstupní hodnotu s mírným navýšením.`,
  rnt = `Akcelerace – střední`,
  int = `Se střední akcelerací je vzdálenost rychlého přejetí prstem po trackpadu převedena na výstupní hodnotu se znatelným navýšením.`,
  ant = `Akcelerace – vysoká`,
  ont = `S vysokou akcelerací je vzdálenost rychlého přejetí prstem po trackpadu převedena na výstupní hodnotu s velkým navýšením.`,
  snt = `Signál po poklepání`,
  cnt = `Poklepáním může být hře odeslán jiný signál (tlačítko/klávesa), který si nastavíte. Pro poklepání není třeba celé stisknutí, pouze dvě rychlá klepnutí po sobě.`,
  lnt = `Prodleva mezi klepnutími`,
  unt = `Prodleva mezi klepnutími určuje dobu, během které budou dvě po sobě jdoucí klepnutí zaznamenána jako poklepání. Čím nižší hodnota této možnosti bude, tím rychleji po sobě budete muset klepnout, aby bylo zaznamenáno poklepání.`,
  dnt = `Pípnutí při poklepání`,
  fnt = `Tato možnost zajistí, aby ovladač pípnul, pokud je zaznamenáno poklepání.`,
  pnt = `Pípnutí při poklepání – zapnuto`,
  mnt = `Tato možnost zajistí, aby ovladač pípnul, pokud je zaznamenáno poklepání.`,
  hnt = `Pípnutí při poklepání – vypnuto`,
  gnt = `Tato možnost zajistí, aby ovladač pípnul, pokud je zaznamenáno poklepání.`,
  _nt = `Tlumení myši stiskem spoušti`,
  vnt = `Pohyby myši lze utlumit při stisknutí spouště, dokud není dosaženo jejího úplného stisknutí. Tím lze zamezit nechtěnému pohybu při ovládání spouští.`,
  ynt = `Rozsah posunování za okrajem`,
  bnt = `Rozsah oblasti pro posunování za okrajem. Posuvník si lze představit jako rozšiřující se poloměr od středu ven, kdy puntík úplně vlevo znamená posunování za okrajem po celé ploše a puntík úplně vpravo posunování až na úplném, opravdovém okraji trackpadu.`,
  xnt = `Rychlost posunování za okrajem`,
  Snt = `Pokud je nastavena rychlost posunování za okrajem a myš se dostane mimo rozsah nastavený v „Rozsah posunování za okrajem“, začne odesílat signál značící konstantní rychlost daným směrem, kterým míří.`,
  Cnt = `Páčka pro signály`,
