  knt = `Invertování vodorovné osy – zapnuto`,
  Ant = `Pokud je možnost zapnuta, pohyb myší doleva vyvolá ve hře pohyb doprava a naopak. Pozor na to, že v některých hrách lze nastavit to samé, takže se nastavení mohou vzájemně vyrušovat.`,
  jnt = `Invertování vodorovné osy – vypnuto`,
  Mnt = `Pohyb myší doleva vyvolá ve hře pohyb doleva, pohyb po vodorovné ose je tedy nezměněný.`,
  Nnt = `Invertování svislé osy`,
  Pnt = `Pokud je možnost zapnuta, pohyb myší nahoru vyvolá ve hře pohyb dolů a naopak. Pozor na to, že v některých hrách lze nastavit to samé, takže se nastavení mohou vzájemně vyrušovat.`,
  Fnt = `Invertování svislé osy – zapnuto`,
  Int = `Pokud je možnost zapnuta, pohyb myší nahoru vyvolá ve hře pohyb dolů a naopak. Pozor na to, že v některých hrách lze nastavit to samé, takže se nastavení mohou vzájemně vyrušovat.`,
  Lnt = `Invertování svislé osy – vypnuto`,
  Rnt = `Pohyb myší nahoru vyvolá ve hře pohyb nahoru, pohyb po svislé ose je tedy nezměněný.`,
  znt = `Práh pohybu`,
  Bnt = `Myš bude střádat pohyb, dokud nebude překročen tento práh, a teprve poté odešle signál s celkovou délkou pohybu. Tato možnost je určena pro ovládání aplikací vykazujících agresivní filtrování/upínání pohybu myši, kvůli kterému dojde ke ztrátě malých pohybů. Hodnota by měla být co nejnižší.`,
  Vnt = `Tlačítko pro zapnutí gyroskopu`,
  Hnt = `Vstup gyroskopu může být zapnut pouze po stisku určeného tlačítka.`,
