  qnt = `Tlačítko pro zapnutí gyroskopu – dotek levého trackpadu`,
  Jnt = `Vstup gyroskopu bude aktivní pouze při dotýkání se levého trackpadu.`,
  Ynt = `Tlačítko pro zapnutí gyroskopu – dotek jednotného trackpadu`,
  Xnt = `Vstup gyroskopu bude aktivní pouze při dotýkání se libovolné části trackpadu.`,
  Znt = `Tlačítko pro zapnutí gyroskopu – stisk pravého trackpadu`,
  Qnt = `Vstup gyroskopu bude aktivní pouze při stisknutí pravého trackpadu.`,
